"""Guided tours generated by deterministic traversal of the project snapshot.

Every step comes from observed graph data (files, symbols, IMPORTS, CALLS, INHERITS,
HAS_METHOD) and the inferred architecture. Steps that rely on interpretation rather than
an observed relationship (e.g. "this import suggests the next stop") carry
`observed=False`. Nothing is invented when the call graph is incomplete; the tour says so.
The optional narration asks the LLM to describe the tour's evidence, never to extend it.
"""

from collections import Counter
from typing import Any, Literal

from pydantic import BaseModel

from codeatlas.intel.architecture import (LAYER_TITLES, LAYERS, UNCLASSIFIED,
                                          ArchitectureReport, layer_of_file)
from codeatlas.intel.snapshot import Snapshot

TOUR_KINDS = ("overview", "entry", "component", "execution", "dependency", "impact")
MAX_STEPS = 25
CONF_ORDER = {"exact": 0, "name_match": 1}


class TourError(ValueError):
    pass


class TourStep(BaseModel):
    index: int
    title: str
    explanation: str
    kind: Literal["layer", "component", "file", "symbol", "module", "summary"]
    node_id: str | None = None
    node_label: str | None = None
    layer: str | None = None
    component: str | None = None
    location: dict[str, Any] | None = None
    evidence: list[str] = []
    observed: bool = True  # False: an inferred step, not a directly observed relationship


class Tour(BaseModel):
    kind: str
    title: str
    purpose: str
    target: str | None = None
    steps: list[TourStep] = []
    notes: list[str] = []
    truncated: bool = False
    narrative: str | None = None
    llm_error: dict[str, Any] | None = None


class _Builder:
    def __init__(self, snap: Snapshot, report: ArchitectureReport):
        self.snap, self.report = snap, report
        self.file_ctx = layer_of_file(report)
        self.comp = {c.name: c for c in report.components}
        self.steps: list[TourStep] = []
        self.truncated = False

    def ctx(self, nid: str) -> tuple[str | None, str | None]:
        n = self.snap.nodes.get(nid) or {}
        path = n.get("path") or n.get("file_path")
        return self.file_ctx.get(path, (None, None)) if path else (None, None)

    def add(self, title: str, explanation: str, kind: str, node_id: str | None = None,
            evidence: list[str] | None = None, observed: bool = True,
            layer: str | None = None, component: str | None = None) -> bool:
        if len(self.steps) >= MAX_STEPS:
            self.truncated = True
            return False
        if node_id:
            component, layer = self.ctx(node_id) if component is None else (component, layer)
        self.steps.append(TourStep(
            index=len(self.steps), title=title, explanation=explanation, kind=kind,
            node_id=node_id, node_label=self.snap.label(node_id) if node_id else None,
            layer=layer, component=component,
            location=self.snap.location(node_id) if node_id else None,
            evidence=evidence or [], observed=observed))
        return True

    def symbol_step(self, nid: str, title: str, explanation: str, evidence=None,
                    observed=True) -> bool:
        n = self.snap.nodes[nid]
        kind = "file" if n["label"] == "File" else "module" if n["label"] == "Module" \
            else "symbol"
        doc = _first_line(n.get("docstring"))
        if doc:
            explanation += f" Docstring: “{doc}”"
        return self.add(title, explanation, kind, nid, evidence, observed)


def _first_line(text: str | None) -> str | None:
    if not text:
        return None
    line = text.strip().splitlines()[0].strip()
    return line[:160] or None


def _lines(e) -> str:
    lines = e.props.get("lines") or []
    return ", ".join(map(str, lines[:5])) + ("…" if len(lines) > 5 else "") if lines else "?"


def _callers(snap: Snapshot, nid: str) -> int:
    return len(snap.in_edges(nid, "CALLS"))


def _symbols_in_file(snap: Snapshot, fid: str) -> list[str]:
    out = []
    for e in sorted(snap.out_edges(fid, "DEFINES"), key=lambda e: e.target):
        out.append(e.target)
        out += sorted(m.target for m in snap.out_edges(e.target, "HAS_METHOD"))
    return [s for s in out if s in snap.nodes]


def _files_of_component(snap: Snapshot, report: ArchitectureReport, comp: str) -> list[str]:
    paths = set(next(c.files for c in report.components if c.name == comp))
    return [f["id"] for f in snap.of_label("File") if f.get("path") in paths]


# ------------------------------------------------------------------ tours

def overview_tour(snap: Snapshot, report: ArchitectureReport) -> Tour:
    b = _Builder(snap, report)
    edges_from = Counter()
    for le in report.layer_edges:
        edges_from[le.source] += le.imports
    for summary in report.layers:
        comps = [b.comp[c] for c in summary.components]
        out = [f"{LAYER_TITLES[e.target]} ({e.imports})" for e in report.layer_edges
               if e.source == summary.layer]
        inc = [f"{LAYER_TITLES[e.source]} ({e.imports})" for e in report.layer_edges
               if e.target == summary.layer]
        names = ", ".join(c.name for c in comps[:8]) + ("…" if len(comps) > 8 else "")
        text = (f"{len(comps)} component(s), {summary.file_count} file(s): {names}. "
                f"Depends on: {', '.join(out) or 'no other layer'}. "
                f"Used by: {', '.join(inc) or 'no other layer'}.")
        if summary.layer == UNCLASSIFIED:
            text += " These components had too little or conflicting evidence to classify."
        ev = [f"{c.name}: {c.confidence} confidence — " + "; ".join(c.evidence[:2])
              for c in comps[:4]]
        b.add(summary.title, text, "layer", evidence=ev, observed=False, layer=summary.layer)
    if report.entry_points:
        b.add("Entry points", "Execution most likely starts in: " +
              ", ".join(report.entry_points[:6]) + ". Start an entry-point tour to follow "
              "their calls.", "summary", evidence=report.entry_points[:6], observed=False)
    if report.component_cycles:
        b.add("Tightly coupled components",
              f"{len(report.component_cycles)} group(s) of components import each other "
              "(cycles): " + "; ".join(" ↔ ".join(c) for c in report.component_cycles[:3]),
              "summary", evidence=[" ↔ ".join(c) for c in report.component_cycles[:5]])
    if report.violations:
        b.add("Possible layering violations",
              "Dependencies that run against the conventional direction (inferred).",
              "summary", observed=False,
              evidence=[f"{v.source_component} [{v.source_layer}] → {v.target_component} "
                        f"[{v.target_layer}]: {v.example}" for v in report.violations[:6]])
    notes = list(report.notes)
    if not report.layers:
        notes.append("The project has no files to tour.")
    return Tour(kind="overview", title=f"Architecture overview of {snap.project_name}",
                purpose="Walk through the inferred layers in dependency order, then the entry "
                        "points, cycles and possible violations.",
                steps=b.steps, notes=notes, truncated=b.truncated)


def _entry_functions(snap: Snapshot, fid: str) -> list[str]:
    syms = [s for s in _symbols_in_file(snap, fid) if snap.label(s) == "Function"]
    mains = [s for s in syms if snap.nodes[s].get("name") == "main"]
    routes = [s for s in syms if any(any(k in d for k in (".get", ".post", ".put", ".delete",
                                                           ".route", ".command"))
                                     for d in snap.nodes[s].get("decorators") or [])]
    top = [s for s in syms if not snap.nodes[s].get("is_method")]
    for group in (mains, routes, top):
        if group:
            return sorted(group, key=lambda s: snap.nodes[s].get("start_line") or 0)
    return []


def _resolve_file(snap: Snapshot, target: str | None) -> str | None:
    if not target:
        return None
    if snap.label(target) == "File":
        return target
    return next((f["id"] for f in snap.of_label("File") if f.get("path") == target), None)


def entry_tour(snap: Snapshot, report: ArchitectureReport, target: str | None = None) -> Tour:
    tour = Tour(kind="entry", title="Entry-point tour", target=target,
                purpose="Start where execution begins and follow resolved calls outward.")
    entries = [f["id"] for f in snap.of_label("File") if f.get("path") in report.entry_points]
    fid = _resolve_file(snap, target) or (entries[0] if entries else None)
    if fid is None:
        tour.notes.append("No entry point was detected in this project (no `main`, route/CLI "
                          "handler or entry-style file that nothing imports). Pick a file or "
                          "function and start a component or execution-path tour instead.")
        return tour
    b = _Builder(snap, report)
    path = snap.nodes[fid].get("path")
    tour.title = f"Entry-point tour: {path}"
    b.symbol_step(fid, path, "Execution starts in this file "
                  + ("(detected entry point)." if fid in entries else "(selected)."),
                  observed=fid in entries)
    starts = _entry_functions(snap, fid)
    if not starts:
        tour.notes.append("The entry file defines no functions; nothing to follow.")
    frontier, seen, depth = list(starts), set(starts), 0
    for s in starts:
        b.symbol_step(s, snap.nodes[s].get("qualname"), "Entry function defined in "
                      f"{path} (lines {snap.nodes[s].get('start_line')}–"
                      f"{snap.nodes[s].get('end_line')}).")
    any_calls = False
    while frontier and depth < 4:
        depth += 1
        nxt = []
        for caller in frontier:
            edges = sorted(snap.out_edges(caller, "CALLS"),
                           key=lambda e: (CONF_ORDER.get(e.props.get("confidence"), 2), e.target))
            for e in edges:
                if e.target in seen or e.target not in snap.nodes:
                    continue
                seen.add(e.target)
                any_calls = True
                conf = e.props.get("confidence", "unknown")
                if not b.symbol_step(
                        e.target, snap.nodes[e.target].get("qualname"),
                        f"Called by {snap.nodes[caller].get('qualname')} at line(s) {_lines(e)} "
                        f"(call resolution: {conf}; depth {depth}).",
                        evidence=[f"{snap.display(caller)} -CALLS-> {snap.display(e.target)}"],
                        observed=True):
                    break
                nxt.append(e.target)
        frontier = nxt
    if starts and not any_calls:
        tour.notes.append("No resolved calls leave the entry functions, so the execution path "
                          "cannot be traced. Following the entry file's imports instead "
                          "(inferred: an import does not prove execution).")
        for e in sorted(snap.out_edges(fid, "IMPORTS"), key=lambda e: e.target):
            if snap.label(e.target) == "File":
                b.symbol_step(e.target, snap.nodes[e.target].get("path"),
                              f"Imported by {path} at line(s) {_lines(e)}.",
                              evidence=[f"{path} -IMPORTS-> {snap.display(e.target)}"],
                              observed=False)
    unresolved = sorted({u for s in seen for u in snap.nodes[s].get("unresolved_calls") or []})
    if unresolved:
        tour.notes.append("Calls the analyzer could not resolve (not followed): "
                          + ", ".join(unresolved[:15]))
    tour.steps, tour.truncated = b.steps, b.truncated
    return tour


def component_tour(snap: Snapshot, report: ArchitectureReport, target: str) -> Tour:
    comp = next((c for c in report.components if c.name == target), None)
    if comp is None:
        raise TourError(f"Unknown component {target!r}")
    b = _Builder(snap, report)
    b.add(f"{comp.name} ({LAYER_TITLES[comp.layer]})",
          f"Inferred layer: {LAYER_TITLES[comp.layer]} ({comp.confidence} confidence). "
          f"{len(comp.files)} file(s), {comp.symbol_count} symbol(s), {comp.loc} lines."
          + (f" Ambiguous between: {', '.join(comp.ambiguous_between)}."
             if comp.ambiguous_between else ""),
          "component", evidence=comp.evidence, observed=False, layer=comp.layer,
          component=comp.name)
    fids = _files_of_component(snap, report, comp.name)
    fids.sort(key=lambda f: (-len(snap.in_edges(f, "IMPORTS")), snap.nodes[f].get("path")))
    for fid in fids[:8]:
        syms = _symbols_in_file(snap, fid)
        key = sorted(syms, key=lambda s: (-_callers(snap, s), s))[:3]
        b.symbol_step(fid, snap.nodes[fid].get("path"),
                      f"Defines {len(syms)} symbol(s); imported by "
                      f"{len(snap.in_edges(fid, 'IMPORTS'))} file(s). Key symbols: "
                      + (", ".join(snap.nodes[s].get("qualname") for s in key) or "none") + ".")
    symbols = [s for f in fids for s in _symbols_in_file(snap, f)]
    important = sorted(symbols, key=lambda s: (-_callers(snap, s), s))[:5]
    for s in important:
        if _callers(snap, s) == 0:
            break
        callers = sorted({snap.display(e.source) for e in snap.in_edges(s, "CALLS")})
        b.symbol_step(s, snap.nodes[s].get("qualname"),
                      f"One of the most-called symbols here: {len(callers)} known caller(s).",
                      evidence=callers[:6])
    if comp.depends_on or comp.used_by:
        b.add("Dependencies", "Depends on: " + (", ".join(
            f"{d.component} ({d.imports} imports)" for d in comp.depends_on[:8]) or "nothing")
            + ". Used by: " + (", ".join(f"{d.component} ({d.imports})"
                                         for d in comp.used_by[:8]) or "nothing") + ".",
            "summary", layer=comp.layer, component=comp.name)
    return Tour(kind="component", title=f"Component tour: {comp.name}", target=target,
                purpose="What this component is, its files, its most-used symbols and its "
                        "dependencies.", steps=b.steps, truncated=b.truncated)


def execution_tour(snap: Snapshot, report: ArchitectureReport, target: str) -> Tour:
    if snap.label(target) != "Function":
        raise TourError("An execution-path tour starts from a function or method id.")
    b = _Builder(snap, report)
    tour = Tour(kind="execution", target=target,
                title=f"Execution path from {snap.nodes[target].get('qualname')}",
                purpose="Follow resolved CALLS depth-first (exact resolutions first).")
    visited: set[str] = set()

    def walk(nid: str, depth: int, via=None):
        if len(b.steps) >= MAX_STEPS:
            b.truncated = True
            return
        n = snap.nodes[nid]
        if via is None:
            text = f"Start: defined in {n.get('file_path')} lines {n.get('start_line')}–" \
                   f"{n.get('end_line')}."
            ev = []
        else:
            text = (f"Depth {depth}: called from {snap.nodes[via.source].get('qualname')}"
                    f" at line(s) {_lines(via)} (resolution: {via.props.get('confidence')}).")
            ev = [f"{snap.display(via.source)} -CALLS-> {snap.display(nid)}"]
        if nid in visited:
            b.add(f"↺ {n.get('qualname')}", text + " Already visited (recursion or cycle); not "
                  "expanded again.", "symbol", nid, ev)
            return
        visited.add(nid)
        ext = (n.get("external_calls") or [])[:6]
        unres = (n.get("unresolved_calls") or [])[:6]
        if ext:
            text += f" Also calls external code: {', '.join(ext)}."
        if unres:
            text += f" Unresolved calls (not followed): {', '.join(unres)}."
        b.symbol_step(nid, n.get("qualname"), text, ev)
        if depth >= 5:
            return
        for e in sorted(snap.out_edges(nid, "CALLS"),
                        key=lambda e: (CONF_ORDER.get(e.props.get("confidence"), 2), e.target)):
            if e.target in snap.nodes:
                walk(e.target, depth + 1, e)

    walk(target, 0)
    if not snap.out_edges(target, "CALLS"):
        tour.notes.append("This function has no resolved outgoing calls; the call graph may be "
                          "incomplete (dynamic dispatch, callbacks and ambiguous names are not "
                          "resolved).")
    tour.notes.append("Only statically resolved calls are followed; `name_match` means the "
                      "callee was matched by a unique name, not by import.")
    tour.steps, tour.truncated = b.steps, b.truncated
    return tour


def dependency_tour(snap: Snapshot, report: ArchitectureReport, target: str) -> Tour:
    comp = next((c for c in report.components if c.name == target), None)
    if comp is None:
        raise TourError(f"Unknown component {target!r}")
    b = _Builder(snap, report)
    b.add(comp.name, f"{LAYER_TITLES[comp.layer]} component that depends on "
          f"{len(comp.depends_on)} other component(s).", "component", observed=False,
          layer=comp.layer, component=comp.name)
    fids = set(_files_of_component(snap, report, comp.name))
    per_dep: dict[str, list[str]] = {}
    externals: Counter = Counter()
    for fid in sorted(fids):
        for e in snap.out_edges(fid, "IMPORTS"):
            tgt = snap.nodes.get(e.target, {})
            if tgt.get("label") == "Module":
                externals[tgt.get("name")] += 1
            elif tgt.get("label") == "File":
                dep = b.file_ctx.get(tgt.get("path"), (None, None))[0]
                if dep and dep != comp.name:
                    per_dep.setdefault(dep, []).append(
                        f"{snap.nodes[fid].get('path')} imports {tgt.get('path')} "
                        f"(line {_lines(e)}; names: {', '.join(e.props.get('names') or []) or '—'})")
    for d in comp.depends_on:
        dep = b.comp.get(d.component)
        b.add(f"→ {d.component}", f"{d.imports} import(s)"
              + (f", {d.calls} resolved call(s)" if d.calls else "")
              + (f". Layer: {LAYER_TITLES[dep.layer]}." if dep else "."), "component",
              evidence=per_dep.get(d.component, [])[:6], layer=dep.layer if dep else None,
              component=d.component)
    if externals:
        b.add("External dependencies", "Third-party / standard-library modules imported: "
              + ", ".join(f"{m} ({n})" for m, n in externals.most_common(12)) + ".", "summary")
    tour = Tour(kind="dependency", title=f"Dependency tour: {comp.name}", target=target,
                purpose="What this component relies on, with the observed imports.",
                steps=b.steps, truncated=b.truncated)
    if not comp.depends_on:
        tour.notes.append("This component imports no other project component.")
    return tour


def impact_tour(snap: Snapshot, report: ArchitectureReport, target: str) -> Tour:
    if target in {c.name for c in report.components}:
        seeds = _files_of_component(snap, report, target)
        title = f"Impact tour: component {target}"
    elif target in snap.nodes:
        seeds = [target]
        title = f"Impact tour: {snap.display(target)}"
    else:
        raise TourError(f"Unknown component or node {target!r}")
    b = _Builder(snap, report)
    # what is "inside" the target: the seeds plus their symbols
    inside = set(seeds)
    for s in seeds:
        if snap.label(s) == "File":
            inside |= set(_symbols_in_file(snap, s))
        if snap.label(s) == "Class":
            inside |= {e.target for e in snap.out_edges(s, "HAS_METHOD")}
    frontier, seen = sorted(inside), set(inside)
    affected_components: Counter = Counter()
    for depth in range(1, 4):
        nxt = []
        for nid in frontier:
            for e in sorted(snap.in_edges(nid), key=lambda e: (e.type, e.source)):
                if e.type not in ("CALLS", "IMPORTS", "INHERITS") or e.source in seen:
                    continue
                seen.add(e.source)
                nxt.append(e.source)
                comp, _ = b.ctx(e.source)
                affected_components[comp] += 1
                verb = {"CALLS": "calls", "IMPORTS": "imports", "INHERITS": "inherits from"}[e.type]
                b.symbol_step(e.source, snap.display(e.source),
                              f"Distance {depth}: {verb} {snap.display(e.target)}"
                              + (f" (line(s) {_lines(e)})" if e.props.get("lines") else "") + ".",
                              evidence=[f"{snap.display(e.source)} -{e.type}-> "
                                        f"{snap.display(e.target)}"])
        frontier = nxt
    affected_components.pop(None, None)
    b.add("Affected components", (", ".join(f"{c} ({n})" for c, n in
                                            affected_components.most_common(10))
                                  or "No known dependents were found.") + "", "summary",
          observed=True)
    tour = Tour(kind="impact", title=title, target=target,
                purpose="Who may be affected by a change: callers, importers and subclasses, "
                        "up to three steps away.", steps=b.steps, truncated=b.truncated)
    tour.notes.append("Based on resolved static relationships only; dynamic use, reflection "
                      "and external consumers are not visible.")
    return tour


def build_tour(snap: Snapshot, report: ArchitectureReport, kind: str,
               target: str | None = None) -> Tour:
    if kind not in TOUR_KINDS:
        raise TourError(f"Unknown tour kind {kind!r}; expected one of {TOUR_KINDS}")
    if kind == "overview":
        return overview_tour(snap, report)
    if kind == "entry":
        return entry_tour(snap, report, target)
    if not target:
        raise TourError(f"A {kind} tour needs a target.")
    return {"component": component_tour, "execution": execution_tour,
            "dependency": dependency_tour, "impact": impact_tour}[kind](snap, report, target)


NARRATE_SYSTEM = (
    "You narrate a guided tour of a code repository for a developer. Use ONLY the steps and "
    "evidence given. Write 1-3 sentences per step, in order, referring to steps by number. "
    "Do not invent files, functions, calls or line numbers. Mark interpretation as such and "
    "say when evidence is missing.")


def tour_prompt(tour: Tour, max_chars: int = 7000) -> str:
    lines = [f"Tour: {tour.title}", f"Purpose: {tour.purpose}"]
    for s in tour.steps:
        loc = s.location or {}
        lines.append(f"{s.index + 1}. {s.title} [{s.layer or '-'}; "
                     f"{'observed' if s.observed else 'inferred'}] {s.explanation} "
                     f"({loc.get('file_path', '')}:{loc.get('start_line') or ''}) "
                     + "; ".join(s.evidence[:3]))
    if tour.notes:
        lines.append("Notes: " + " ".join(tour.notes))
    return "\n".join(lines)[:max_chars]


__all__ = ["TOUR_KINDS", "Tour", "TourError", "TourStep", "build_tour", "NARRATE_SYSTEM",
           "tour_prompt", "LAYERS"]
